-- Seed content for the Bible games. Generated by scripts/build-games-seed.mjs.
-- Run AFTER migration-004-games.sql. Safe to re-run: each game is only
-- seeded while it has no questions yet.

insert into public.game_questions (game, difficulty, payload)
select * from (values
('quiz','easy',$j${"question":"Who built the ark according to God's instructions?","options":["Moses","Noah","Abraham","David"],"correctIndex":1,"reference":"Genesis 6:14","explanation":"God commanded Noah to build an ark of gopherwood, with rooms inside, and cover it inside and out with pitch, in order to save his family and a remnant of all land animals from the global flood.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: NOAH'S ARK COVENANT"}$j$::jsonb),
('quiz','medium',$j${"question":"What is the first book of the Bible?","options":["Exodus","Genesis","Leviticus","Numbers"],"correctIndex":1,"reference":"Genesis 1:1","explanation":"Genesis is the first book of the Hebrew Bible and the Christian Old Testament. Its name comes from the Greek word meaning 'origin' or 'birth', as it narrates the creation of the world and the early history of humanity.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE GENESIS OF CREATION"}$j$::jsonb),
('quiz','hard',$j${"question":"How many days did it take God to create the heavens and the earth (excluding the day of rest)?","options":["5","6","7","8"],"correctIndex":1,"reference":"Genesis 1:31 - 2:2","explanation":"According to the creation narrative in Genesis, God completed the creation of the heavens, the earth, and all their host in six days, and then rested on the seventh day, blessing it and making it holy.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE SEVEN DAYS OF HEAVEN & EARTH"}$j$::jsonb),
('quiz','expert',$j${"question":"Who was swallowed by a great fish when running from God?","options":["Jonah","Daniel","Samson","Joseph"],"correctIndex":0,"reference":"Jonah 1:17","explanation":"When Jonah attempted to flee from God's command to preach in Nineveh by boarding a ship to Tarshish, a great storm arose. The sailors cast him overboard, and God prepared a great fish to swallow Jonah, who remained in its belly for three days and three nights.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: JONAH'S TARSHISH VOYAGE"}$j$::jsonb),
('quiz','easy',$j${"question":"Which apostle betrayed Jesus in the Garden of Gethsemane?","options":["Peter","John","Judas Iscariot","Thomas"],"correctIndex":2,"reference":"Matthew 26:47-49","explanation":"Judas Iscariot, one of the twelve disciples, betrayed Jesus to the chief priests and elders by leading an armed crowd to the Garden of Gethsemane and identifying Jesus with a kiss.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE GARDEN OF GETHSEMANE"}$j$::jsonb),
('quiz','medium',$j${"question":"What did God use to make the first woman, Eve?","options":["Dust of the ground","A rib from Adam","A stone","A tree branch"],"correctIndex":1,"reference":"Genesis 2:21-22","explanation":"God caused a deep sleep to fall upon Adam, took one of his ribs, and closed up the flesh. From the rib, the Lord God made a woman and brought her to the man.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the first murderer recorded in the Bible?","options":["Cain","Abel","Lamech","Esau"],"correctIndex":0,"reference":"Genesis 4:8","explanation":"Cain, the firstborn son of Adam and Eve, killed his younger brother Abel out of jealousy because God looked with favor on Abel's offering but not on Cain's.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"What sign did God place in the sky as a covenant never to flood the earth again?","options":["A shooting star","A rainbow","A pillar of cloud","A solar eclipse"],"correctIndex":1,"reference":"Genesis 9:13","explanation":"God set His rainbow in the cloud as the sign of the covenant between Him and the earth, promising that the waters would never again become a flood to destroy all flesh.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: NOAH'S ARK COVENANT"}$j$::jsonb),
('quiz','easy',$j${"question":"What was Abraham's name before God changed it?","options":["Abimelech","Abram","Abel","Absalom"],"correctIndex":1,"reference":"Genesis 17:5","explanation":"God changed his name from Abram (meaning 'exalted father') to Abraham (meaning 'father of a multitude') as part of His covenant promise.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"Who was Isaac's wife?","options":["Rachel","Rebekah","Leah","Sarah"],"correctIndex":1,"reference":"Genesis 24:67","explanation":"Isaac married Rebekah, who was found by Abraham's servant in Mesopotamia near the city of Nahor, and she brought Isaac comfort after his mother Sarah's death.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"How many sons did Jacob have?","options":["10","12","7","3"],"correctIndex":1,"reference":"Genesis 35:22","explanation":"Jacob had twelve sons, who became the ancestors of the twelve tribes of Israel: Reuben, Simeon, Levi, Judah, Dan, Naphtali, Gad, Asher, Issachar, Zebulun, Joseph, and Benjamin.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"Which of Jacob's sons had a coat of many colors (or a multi-colored tunic)?","options":["Reuben","Judah","Joseph","Benjamin"],"correctIndex":2,"reference":"Genesis 37:3","explanation":"Israel (Jacob) loved Joseph more than any of his other sons because he had been born to him in his old age, and he made an ornate robe (traditionally translated as a coat of many colors) for him.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"What was Moses' brother's name, who spoke for him before Pharaoh?","options":["Aaron","Miriam","Caleb","Joshua"],"correctIndex":0,"reference":"Exodus 4:14","explanation":"Because Moses was slow of speech, God designated his older brother Aaron, a Levite, to speak on his behalf as his spokesman to the people and to Pharaoh.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE EXODUS ROUTE"}$j$::jsonb),
('quiz','medium',$j${"question":"What was the final plague on Egypt before Pharaoh let the Israelites go?","options":["Plague of Frogs","Death of the Firstborn","Hail and Fire","Locusts"],"correctIndex":1,"reference":"Exodus 11:4-5","explanation":"The tenth and final plague was the death of every firstborn in Egypt, from the firstborn of Pharaoh to the firstborn of the slave girl, prompting Pharaoh to finally release Israel.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE EXODUS ROUTE"}$j$::jsonb),
('quiz','hard',$j${"question":"On what mountain did Moses receive the Ten Commandments?","options":["Mount Ararat","Mount Sinai","Mount Nebo","Mount Carmel"],"correctIndex":1,"reference":"Exodus 19:20","explanation":"The Lord descended upon Mount Sinai in fire, called Moses to the top of the mountain, and gave him the Ten Commandments written on stone tablets.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE EXODUS ROUTE"}$j$::jsonb),
('quiz','expert',$j${"question":"What did the Israelites eat in the wilderness that fell from heaven?","options":["Manna","Quail","Figs","Unleavened Bread"],"correctIndex":0,"reference":"Exodus 16:31","explanation":"The house of Israel called the bread from heaven 'manna'. It was white like coriander seed and tasted like wafers made with honey.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"Which of the twelve spies sent into Canaan brought back a good report along with Joshua?","options":["Caleb","Aaron","Korah","Balaam"],"correctIndex":0,"reference":"Numbers 13:30","explanation":"While ten of the spies brought back a discouraging report of giants, Caleb and Joshua stilled the people and urged them to trust God and possess the land.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"What city did the Israelites conquer after marching around its walls for seven days?","options":["Jerusalem","Jericho","Ai","Gibeon"],"correctIndex":1,"reference":"Joshua 6:20","explanation":"On the seventh day, after marching around Jericho seven times, the priests blew the trumpets, the people shouted, and the walls fell down flat.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE SEVEN DAYS OF HEAVEN & EARTH"}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the female judge of Israel who helped defeat the Canaanites?","options":["Ruth","Deborah","Esther","Delilah"],"correctIndex":1,"reference":"Judges 4:4","explanation":"Deborah, a prophetess, was judging Israel at that time. She summoned Barak to lead Israel's army against Sisera, the commander of Jabin's Canaanite army.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"What was the secret of Samson's great strength?","options":["His long hair","His magic sword","His golden belt","His special diet"],"correctIndex":0,"reference":"Judges 16:17","explanation":"Samson was a Nazirite dedicated to God from birth. A razor had never touched his head; if his hair were shaved, his strength would leave him.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"Who was the Moabite woman who remained loyal to her mother-in-law Naomi?","options":["Orpah","Ruth","Delilah","Jezebel"],"correctIndex":1,"reference":"Ruth 1:16","explanation":"Ruth declared to Naomi: 'Where you go I will go, and where you stay I will stay. Your people will be my people and your God my God.'","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"Who was the first king of Israel?","options":["David","Saul","Solomon","Samuel"],"correctIndex":1,"reference":"1 Samuel 10:1","explanation":"Samuel took a flask of olive oil and poured it on Saul's head, anointing him as the first king over Israel by God's direction.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"What weapon did David use to defeat the giant Goliath?","options":["A sword and shield","A sling and a stone","A spear","A bow and arrow"],"correctIndex":1,"reference":"1 Samuel 17:49","explanation":"David reached into his bag, drew out a stone, slung it, and struck the Philistine giant Goliath on the forehead, killing him.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"Who was David's best friend, the son of King Saul?","options":["Jonathan","Abner","Joab","Absalom"],"correctIndex":0,"reference":"1 Samuel 18:1","explanation":"Jonathan's soul was knit to the soul of David, and Jonathan loved him as his own soul, establishing a deep and famous covenant of friendship.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"Which king built the first temple in Jerusalem?","options":["David","Solomon","Rehoboam","Hezekiah"],"correctIndex":1,"reference":"1 Kings 6:1","explanation":"Solomon built the temple of the Lord, a project his father David had planned but was not permitted to build because he was a man of war.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE GLORIOUS TEMPLE OF JERUSALEM"}$j$::jsonb),
('quiz','medium',$j${"question":"Who was the wicked queen of Israel, wife of King Ahab, who opposed Elijah?","options":["Athaliah","Jezebel","Esther","Vashti"],"correctIndex":1,"reference":"1 Kings 16:31","explanation":"Ahab married Jezebel, daughter of Ethbaal king of the Sidonians, who introduced Baal worship to Israel and sought to kill God's prophets.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"How did the prophet Elijah depart from this world?","options":["He died of old age","He was carried to heaven in a whirlwind by a chariot of fire","He was drowned in the Jordan","He was martyred by Ahab"],"correctIndex":1,"reference":"2 Kings 2:11","explanation":"As Elijah and Elisha walked along, a chariot of fire and horses of fire appeared, and Elijah went up in a whirlwind into heaven.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"Who succeeded Elijah as the leading prophet of Israel?","options":["Elisha","Isaiah","Jeremiah","Ezekiel"],"correctIndex":0,"reference":"2 Kings 2:15","explanation":"The company of the prophets from Jericho saw Elisha and said, 'The spirit of Elijah rests on Elisha,' recognizing him as the new leader.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"Which Babylonian king threw Daniel's three friends into the fiery furnace?","options":["Cyrus","Darius","Nebuchadnezzar","Belshazzar"],"correctIndex":2,"reference":"Daniel 3:19-20","explanation":"King Nebuchadnezzar commanded that the fiery furnace be heated seven times hotter than usual and ordered Shadrach, Meshach, and Abednego to be thrown in.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"Where did God write the writing on the wall during Belshazzar's feast?","options":["On the temple altar","On the plaster of the palace wall","On a parchment scroll","On a stone tablet"],"correctIndex":1,"reference":"Daniel 5:5","explanation":"Suddenly, the fingers of a human hand appeared and wrote on the plaster of the wall, near the lampstand in the royal palace.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"In what town was Jesus born?","options":["Nazareth","Jerusalem","Bethlehem","Capernaum"],"correctIndex":2,"reference":"Matthew 2:1","explanation":"Jesus was born in Bethlehem of Judea during the reign of King Herod, fulfilling the prophecy of Micah 5:2.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"Who baptized Jesus in the Jordan River?","options":["John the Baptist","Peter","James","Elijah"],"correctIndex":0,"reference":"Matthew 3:13","explanation":"Jesus came from Galilee to the Jordan to be baptized by John the Baptist, who initially hesitated, saying, 'I need to be baptized by you.'","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"How many apostles did Jesus choose?","options":["10","12","70","3"],"correctIndex":1,"reference":"Matthew 10:1","explanation":"Jesus called His twelve disciples to Him and gave them authority to drive out impure spirits and to heal every disease and sickness.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"What is the shortest verse in the Bible?","options":["John 3:16","John 11:35","Matthew 1:1","Psalm 23:1"],"correctIndex":1,"reference":"John 11:35","explanation":"The verse is simply 'Jesus wept,' occurring when Jesus saw Mary weeping and the Jews who had come with her weeping over the death of Lazarus.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"Which disciple denied knowing Jesus three times before the rooster crowed?","options":["Judas","Peter","Thomas","Andrew"],"correctIndex":1,"reference":"Matthew 26:74-75","explanation":"Following Jesus' arrest, Peter denied knowing Him three times in the high priest's courtyard, after which a rooster crowed, and Peter remembered Jesus' prediction.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"Who was the Roman governor who ordered the crucifixion of Jesus?","options":["Herod Antipas","Pontius Pilate","Caesar Augustus","Felix"],"correctIndex":1,"reference":"Matthew 27:24-26","explanation":"Pontius Pilate, the Roman governor of Judea, washed his hands before the crowd, released Barabbas, and handed Jesus over to be crucified.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"Who was the first person to see the risen Jesus on Easter morning?","options":["Simon Peter","John","Mary Magdalene","Mother Mary"],"correctIndex":2,"reference":"John 20:14-16","explanation":"Mary Magdalene stood weeping outside the empty tomb. She turned around and saw Jesus standing there, though she initially mistook Him for the gardener.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"On what day did the Holy Spirit descend upon the apostles in tongues of fire?","options":["The Passover","The Sabbath","The Day of Pentecost","The Feast of Tabernacles"],"correctIndex":2,"reference":"Acts 2:1-4","explanation":"When the Day of Pentecost came, a sound like a blowing violent wind filled the house, and tongues of fire separated and came to rest on each of the apostles.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the first Christian martyr, stoned to death for his faith?","options":["Stephen","James","Peter","Paul"],"correctIndex":0,"reference":"Acts 7:59-60","explanation":"Stephen, a deacon full of faith and power, was dragged out of Jerusalem and stoned to death by the Jewish council after testifying of seeing Jesus at God's right hand.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"What was Paul's original Jewish name before his conversion on the road to Damascus?","options":["Saul","Silas","Simon","Barnabas"],"correctIndex":0,"reference":"Acts 9:1-4","explanation":"Paul was originally known as Saul of Tarsus, a Pharisee who actively persecuted the early Christian church before encountering Jesus on the road to Damascus.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"In which city were the disciples of Jesus first called 'Christians'?","options":["Jerusalem","Antioch","Rome","Ephesus"],"correctIndex":1,"reference":"Acts 11:26","explanation":"Barnabas and Saul met with the church in Antioch for a whole year and taught great numbers of people. The disciples were first called Christians there.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"Which is the last book of the New Testament?","options":["Jude","Revelation","Hebrews","Romans"],"correctIndex":1,"reference":"Revelation 1:1","explanation":"The Book of Revelation (or Apocalypse) is the final book of the New Testament, containing apocalyptic prophecies written by John on the island of Patmos.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"How many books are in the Protestant Bible?","options":["66","73","27","39"],"correctIndex":0,"reference":"Bible Overview","explanation":"The standard Protestant Bible contains 66 books: 39 in the Old Testament and 27 in the New Testament.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"How many books are in the New Testament?","options":["27","39","46","12"],"correctIndex":0,"reference":"Bible Overview","explanation":"The New Testament consists of exactly 27 books, starting with the Gospel of Matthew and ending with the Book of Revelation.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"What did Jacob dream of that reached from earth to heaven?","options":["A golden bridge","A ladder with angels ascending and descending","A chariot of fire","A great tree"],"correctIndex":1,"reference":"Genesis 28:12","explanation":"During his journey to Haran, Jacob slept and dreamed of a ladder set up on the earth, with its top reaching to heaven, and angels of God ascending and descending on it.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"What did God change Jacob's name to after he wrestled with an angel?","options":["Abraham","Israel","Isaac","Judah"],"correctIndex":1,"reference":"Genesis 32:28","explanation":"The angel said, 'Your name will no longer be Jacob, but Israel, because you have struggled with God and with humans and have overcome.'","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"What did Moses see in the desert that burned but was not consumed?","options":["A campfire","A burning bush","A glowing cloud","A pillar of salt"],"correctIndex":1,"reference":"Exodus 3:2","explanation":"The angel of the Lord appeared to Moses in flames of fire from within a bush. Moses saw that though the bush was on fire it did not burn up.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE EXODUS ROUTE"}$j$::jsonb),
('quiz','expert',$j${"question":"What was the first plague God brought upon Egypt through Moses?","options":["Water turned into blood","Frogs","Lice","Darkness"],"correctIndex":0,"reference":"Exodus 7:20","explanation":"Moses and Aaron did as the Lord commanded. Aaron raised his staff and struck the water of the Nile, and all the water turned into blood.","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE EXODUS ROUTE"}$j$::jsonb),
('quiz','easy',$j${"question":"How did the Israelites cross the Red Sea to escape the Egyptian army?","options":["By building a bridge of boats","The waters were parted by God","By swimming","They sailed on Noah's Ark"],"correctIndex":1,"reference":"Exodus 14:21-22","explanation":"Moses stretched out his hand over the sea, and the Lord drove the sea back with a strong east wind, turning it into dry land. The waters were divided.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE EXODUS ROUTE"}$j$::jsonb),
('quiz','medium',$j${"question":"What was stored inside the Ark of the Covenant?","options":["The gold of Egypt","The Ten Commandments","The bones of Joseph","The crown of Saul"],"correctIndex":1,"reference":"Hebrews 9:4","explanation":"According to scripture, the Ark of the Covenant contained the golden jar of manna, Aaron's rod that budded, and the stone tablets of the Covenant (Ten Commandments).","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: NOAH'S ARK COVENANT"}$j$::jsonb),
('quiz','hard',$j${"question":"Who did God choose to lead the Israelites into the Promised Land after Moses died?","options":["Aaron","Joshua","Caleb","Gideon"],"correctIndex":1,"reference":"Joshua 1:1-2","explanation":"After the death of Moses, God said to Joshua son of Nun: 'Moses my servant is dead. Now then, you and all these people, get ready to cross the Jordan River.'","testament":"OLD TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE EXODUS ROUTE"}$j$::jsonb),
('quiz','expert',$j${"question":"How did God make the sun stand still for Joshua during battle?","options":["By stopping the rotation of the earth","By delaying the sunset","By sending a solar eclipse","By lengthening the day"],"correctIndex":1,"reference":"Joshua 10:12-13","explanation":"Joshua spoke to the Lord, and the sun stood still and the moon stopped, in the midst of heaven, and delayed going down about a full day so Israel could complete their victory.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"Which judge of Israel defeated an entire army with only 300 men?","options":["Samson","Gideon","Barak","Jephthah"],"correctIndex":1,"reference":"Judges 7:7","explanation":"God told Gideon: 'With the three hundred men that lapped I will save you and give the Midianites into your hands.'","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"Who was the grandmother of King David?","options":["Ruth","Naomi","Rahab","Bathsheba"],"correctIndex":0,"reference":"Ruth 4:21-22","explanation":"Boaz was the father of Obed, Obed was the father of Jesse, and Jesse was the father of David. Boaz's wife was Ruth, making her David's great-grandmother (and Naomi her mother-in-law).","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the priest who raised Samuel in the tabernacle?","options":["Eli","Aaron","Zadok","Melchizedek"],"correctIndex":0,"reference":"1 Samuel 1:24-28","explanation":"Hannah brought her young son Samuel to the house of the Lord at Shiloh, presenting him to Eli the priest to serve God all his days.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','expert',$j${"question":"What was David's occupation before he was anointed king?","options":["Blacksmith","Shepherd","Fisherman","Carpenter"],"correctIndex":1,"reference":"1 Samuel 16:11","explanation":"When Samuel came to Jesse to choose a king, David was out in the fields tending his father's sheep, being the youngest son.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','easy',$j${"question":"Which of David's sons rebelled against him and got his hair caught in a tree?","options":["Solomon","Absalom","Adonijah","Amnon"],"correctIndex":1,"reference":"2 Samuel 18:9","explanation":"During the battle in the forest of Ephraim, Absalom's mule went under the thick branches of a large oak, and Absalom's head got caught, leaving him hanging in midair.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: SCRIPTURE MAP & DIALOGUES"}$j$::jsonb),
('quiz','medium',$j${"question":"For what gift did Solomon ask God when he became king?","options":["Wealth","Long life","Wisdom","Victory over enemies"],"correctIndex":2,"reference":"1 Kings 3:9","explanation":"Solomon asked God for an understanding heart (wisdom) to judge the people and discern between good and evil, which pleased God.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE GLORIOUS TEMPLE OF JERUSALEM"}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the queen who visited Solomon to test him with hard questions?","options":["Queen of Sheba","Queen Esther","Queen Jezebel","Queen Athaliah"],"correctIndex":0,"reference":"1 Kings 10:1","explanation":"When the Queen of Sheba heard about the fame of Solomon and his relationship to the Lord, she came to test him with hard questions.","testament":"NEW TESTAMENT","caption":"REFERENCE ILLUSTRATION: THE GLORIOUS TEMPLE OF JERUSALEM"}$j$::jsonb),
