('quiz','hard',$j${"question":"Who were the Nephilim?","options":["Giants in the land","Angels","Fallen warriors","Descendants of Cain"],"correctIndex":0,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
