('quiz','hard',$j${"question":"What was the sign of God's covenant with Noah?","options":["A star","A rainbow","A cloud","A dove"],"correctIndex":1,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Where did Noah's ark rest?","options":["Mount Sinai","Mount Hermon","Mount Ararat","Mount Zion"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What was the Tower of Babel built to reach?","options":["The clouds","The heavens","God's throne","The moon"],"correctIndex":1,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Where was the Tower of Babel built?","options":["Canaan","Egypt","Babel/Babylon","Mesopotamia"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What language did all people speak before the Tower of Babel?","options":["Hebrew","Aramaic","One common language","Sumerian"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who was Abraham's original home city?","options":["Haran","Damascus","Ur of the Chaldeans","Babylon"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Which prophet was taken to heaven in a chariot of fire?","options":["Elisha","Enoch","Moses","Elijah"],"correctIndex":3,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who succeeded Elijah as prophet?","options":["Elisha","Isaiah","Micah","Amos"],"correctIndex":0,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who were the parents of John the Baptist?","options":["Joseph and Mary","Zechariah and Elizabeth","Simeon and Anna","Eli and Hannah"],"correctIndex":1,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What was the name of the angel who told Zechariah he would have a son?","options":["Michael","Uriel","Raphael","Gabriel"],"correctIndex":3,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Where was Zechariah when Gabriel appeared to him?","options":["In the Temple","In his home","In the wilderness","At the Jordan River"],"correctIndex":0,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What sign was given to Zechariah for doubting the angel?","options":["He became blind","He became deaf","He became mute","He became ill"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the prophetess who recognized Jesus when he was brought to the temple as a baby?","options":["Miriam","Deborah","Anna","Huldah"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who was Simeon?","options":["A priest","A scribe","A righteous devout man","A prophet"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What did Simeon say he could now do after seeing Jesus?","options":["Live a long life","Depart in peace","Prophesy openly","Return to his home"],"correctIndex":1,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"At what age did Jesus first visit the Temple in Jerusalem?","options":["8","10","12","14"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What was the name of the pool where Jesus healed a blind man by making mud?","options":["Bethesda","Siloam","Gibeon","Kidron"],"correctIndex":1,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the Roman governor who sentenced Jesus to death?","options":["Herod","Caesar","Pilate","Festus"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the Herod who killed John the Baptist?","options":["Herod the Great","Herod Antipas","Herod Agrippa I","Herod Philip"],"correctIndex":1,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What was the name of Herod Antipas' wife who demanded John's head?","options":["Salome","Herodias","Bernice","Drusilla"],"correctIndex":1,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who was Herod Antipas' wife's daughter who danced for John's head?","options":["Bernice","Drusilla","Herodias","Salome"],"correctIndex":3,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the tax collector in Jericho that Jesus called?","options":["Matthew","Zacchaeus","Levi","Simon"],"correctIndex":1,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What is the name of the woman who washed Jesus' feet with perfume and her hair?","options":["Mary of Bethany","Mary Magdalene","Martha","Joanna"],"correctIndex":0,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What is the name of the pool in Jerusalem with five porches?","options":["Siloam","Kidron","Bethesda","Gibeon"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What is the name of the valley outside Jerusalem associated with judgment?","options":["Kidron Valley","Valley of Jezreel","Hinnom Valley (Gehenna)","Valley of Elah"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"Who was the first bishop/overseer of the church at Ephesus according to tradition?","options":["Paul","Silas","Timothy","Titus"],"correctIndex":2,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb),
('quiz','hard',$j${"question":"What is the name of the island where Paul was shipwrecked?","options":["Crete","Cyprus","Patmos","Malta"],"correctIndex":3,"reference":"","explanation":"","testament":"OLD TESTAMENT","caption":""}$j$::jsonb)
) as v(game, difficulty, payload)
where not exists (select 1 from public.game_questions where game = 'quiz');

insert into public.game_questions (game, difficulty, payload)
select * from (values
('quote',null,$j${"reference":"Philippians 4:13","hint":"Paul's confident declaration, written from a prison cell, about contentment in every circumstance.","funFact":"Paul wrote this from prison. In context, the 'all things' he refers to is contentment in both scarcity and abundance — not physical achievements or success, which is how the verse is frequently misapplied today.","translations":{"modern":{"text":"I can do all things through {{Christ}} who {{strengthens}} me.","synonyms":{"christ":["him","jesus","god"]}},"kjv":{"text":"I can do all things through {{Christ}} which {{strengtheneth}} me.","synonyms":{"christ":["him","jesus","god"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"John 3:16","hint":"Perhaps the most quoted verse in the Bible, describing God's gift of His Son to the world.","funFact":"The word translated as 'only' (monogenes) in ancient Greek literally means 'unique' or 'one-of-a-kind' rather than 'only begotten' in a biological sense.","translations":{"modern":{"text":"For God so loved the {{world}}, that he gave his only {{Son}}, that whoever {{believes}} in him should not perish but have eternal life.","easyIndex":1},"kjv":{"text":"For God so loved the {{world}}, that he gave his only begotten {{Son}}, that whosoever {{believeth}} in him should not perish, but have everlasting life.","easyIndex":1}}}$j$::jsonb),
('quote',null,$j${"reference":"Psalm 23:1","hint":"The opening line of David's most beloved psalm about the Lord's care and provision.","funFact":"The phrase 'I shall not want' does not mean 'I do not want the Lord,' but rather 'I will lack nothing' or 'I have everything I need.'","translations":{"modern":{"text":"The Lord is my {{shepherd}}; I shall not {{want}}."},"kjv":{"text":"The LORD is my {{shepherd}}; I shall not {{want}}."}}}$j$::jsonb),
('quote',null,$j${"reference":"Jeremiah 29:11","hint":"A promise from God to Israelite exiles in Babylon about hope for their future.","funFact":"This letter was addressed to Jewish exiles in Babylon facing 70 years of captivity. The promise was for long-term community restoration and patience, rather than immediate personal success.","translations":{"modern":{"text":"For I know the {{plans}} I have for you, declares the Lord, plans for {{welfare}} and not for evil, to give you a {{future}} and a hope.","easyIndex":1,"synonyms":{"welfare":["peace","prosperity","good","hope"]}},"kjv":{"text":"For I know the {{thoughts}} that I think toward you, saith the LORD, thoughts of {{peace}}, and not of evil, to give you {{an expected end}}.","easyIndex":1}}}$j$::jsonb),
('quote',null,$j${"reference":"Romans 8:28","hint":"An assurance that God works everything together for the benefit of those who love Him.","funFact":"The ancient Greek syntax allows two readings: 'all things work together for good' or 'God works all things together for good.' Most modern translations prefer the latter, emphasizing God's active hand.","translations":{"modern":{"text":"And we know that for those who {{love}} God all things work together for {{good}}, for those who are called according to his {{purpose}}.","easyIndex":1,"synonyms":{"good":["goodness"]}},"kjv":{"text":"And we know that all things work together for {{good}} to them that {{love}} God, to them who are the called according to his {{purpose}}.","easyIndex":0,"synonyms":{"good":["goodness"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"Proverbs 3:5","hint":"A classic proverb urging full reliance on God rather than one's own reasoning.","funFact":"The Hebrew verb for 'trust' (batach) has the root meaning 'to lie face down,' illustrating a physical posture of absolute surrender, safety, and reliance.","translations":{"modern":{"text":"Trust in the Lord with all your {{heart}}, and do not lean on your own {{understanding}}.","easyIndex":1,"synonyms":{"understanding":["wisdom","mind"]}},"kjv":{"text":"Trust in the LORD with all thine {{heart}}; and lean not unto thine own {{understanding}}.","easyIndex":1,"synonyms":{"understanding":["wisdom","mind"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"Genesis 1:1","hint":"The very first verse of the Bible, describing the start of creation.","funFact":"The Hebrew word for beginning is 'Bereshit'. In Jewish tradition, the Torah starts with the letter Bet (B) rather than Alef (A) because Bet is closed on three sides and open only forward, representing looking ahead.","translations":{"modern":{"text":"In the {{beginning}} God {{created}} the heavens and the earth."},"kjv":{"text":"In the {{beginning}} God {{created}} the heaven and the earth."}}}$j$::jsonb),
('quote',null,$j${"reference":"Matthew 28:19","hint":"The Great Commission, Jesus' final instruction to His disciples before ascending.","funFact":"In the original Greek, the only command verb is 'make disciples'. 'Go' is a participle meaning 'having gone' or 'as you go,' indicating this should occur during daily life.","translations":{"modern":{"text":"Go therefore and make {{disciples}} of all {{nations}}, baptizing them in the name of the Father and of the Son and of the Holy Spirit.","synonyms":{"disciples":["followers"]}},"kjv":{"text":"Go ye therefore, and {{teach}} all {{nations}}, baptizing them in the name of the Father, and of the Son, and of the Holy {{Ghost}}:","synonyms":{"ghost":["spirit"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"Isaiah 40:31","hint":"A promise of renewed strength for those who wait on the Lord, likened to a soaring bird.","funFact":"The Hebrew word for 'wait' (qavah) originally meant 'to bind together' or 'to twist like a rope,' implying that waiting is an active process of binding oneself to God's strength.","translations":{"modern":{"text":"but they who wait for the Lord shall {{renew}} their strength; they shall mount up with wings like {{eagles}}; they shall run and not be {{weary}}; they shall walk and not faint.","easyIndex":1,"synonyms":{"eagles":["eagle"]}},"kjv":{"text":"But they that wait upon the LORD shall {{renew}} their strength; they shall mount up with wings as {{eagles}}; they shall run, and not be {{weary}}; and they shall walk, and not faint.","easyIndex":1,"synonyms":{"eagles":["eagle"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"2 Timothy 1:7","hint":"Paul reminds Timothy of the kind of spirit God has given believers — not one of timidity.","funFact":"The Greek word translated as 'fear' here (deilia) refers specifically to cowardice or timidity, distinct from a healthy, respectful fear of God (yirah).","translations":{"modern":{"text":"for God gave us a spirit not of {{fear}} but of {{power}} and {{love}} and self-control.","easyIndex":2,"synonyms":{"love":["charity"]}},"kjv":{"text":"For God hath not given us the spirit of {{fear}}; but of {{power}}, and of {{love}}, and of a sound mind.","easyIndex":2,"synonyms":{"love":["charity"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"Romans 12:2","hint":"Paul's call to be changed from the inside rather than shaped by the surrounding culture.","funFact":"The Greek word for 'conformed' (syschematizo) refers to a temporary outward styling, whereas 'transformed' (metamorphoo) refers to a deep, permanent change of nature.","translations":{"modern":{"text":"Do not be {{conformed}} to this world, but be {{transformed}} by the renewal of your {{mind}}, that by testing you may discern what is the will of God, what is good and acceptable and perfect.","easyIndex":2,"synonyms":{"mind":["minds","soul","heart"]}},"kjv":{"text":"And be not {{conformed}} to this world: but be ye {{transformed}} by the renewing of your {{mind}}, that ye may prove what is that good, and acceptable, and perfect, will of God.","easyIndex":2,"synonyms":{"mind":["minds","soul","heart"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"Joshua 1:9","hint":"God’s charge to Joshua as he prepares to lead Israel into the Promised Land.","funFact":"This command was given to Joshua immediately after Moses' death, as he stood at the boundary of the Promised Land facing highly fortified cities.","translations":{"modern":{"text":"Have I not commanded you? Be {{strong}} and {{courageous}}. Do not be frightened, and do not be dismayed, for the Lord your God is with you wherever you {{go}}.","easyIndex":2,"synonyms":{"go":["walk","travel"]}},"kjv":{"text":"Have not I commanded thee? Be {{strong}} and of a good {{courage}}; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou {{goest}}.","easyIndex":2,"synonyms":{"goest":["go","walk","travel"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"Micah 6:8","hint":"The prophet's summary of what the Lord truly requires of His people.","funFact":"The Hebrew word translated as 'kindness' or 'mercy' is 'chesed', a rich theological term representing covenant commitment, loyalty, and active relational devotion.","translations":{"modern":{"text":"He has told you, O man, what is good; and what does the Lord require of you but to do {{justice}}, and to love {{kindness}}, and to walk {{humbly}} with your God?","easyIndex":1,"synonyms":{"kindness":["mercy","mercy and kindness"]}},"kjv":{"text":"He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do {{justly}}, and to love {{mercy}}, and to walk {{humbly}} with thy God?","easyIndex":1,"synonyms":{"justly":["justice"],"mercy":["kindness"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"Matthew 6:33","hint":"Jesus' instruction to prioritize God's kingdom above worldly worries.","funFact":"In the context of the Sermon on the Mount, 'all these things' refers specifically to basic human needs like food and clothing, about which Jesus tells His followers not to worry.","translations":{"modern":{"text":"But seek first the {{kingdom}} of God and his {{righteousness}}, and all these things will be added to you."},"kjv":{"text":"But seek ye first the {{kingdom}} of God, and his {{righteousness}}; and all these things shall be added unto you."}}}$j$::jsonb),
('quote',null,$j${"reference":"John 14:6","hint":"Jesus' statement to His disciples about being the only way to the Father.","funFact":"In the early Church, prior to being called 'Christians', believers were referred to as followers of 'The Way,' directly referencing this scripture.","translations":{"modern":{"text":"Jesus said to him, 'I am the {{way}}, and the {{truth}}, and the {{life}}. No one comes to the Father except through me.'","easyIndex":2},"kjv":{"text":"Jesus saith unto him, I am the {{way}}, the {{truth}}, and the {{life}}: no man cometh unto the Father, but by me.","easyIndex":2}}}$j$::jsonb),
('quote',null,$j${"reference":"Galatians 5:22","hint":"The beginning of Paul's list of virtues produced by the Holy Spirit in a believer's life.","funFact":"Paul uses the singular word 'fruit' (karpos) rather than 'fruits' to emphasize that these virtues form a unified, indivisible whole representing Christian character.","translations":{"modern":{"text":"But the fruit of the Spirit is love, joy, peace, patience, {{kindness}}, {{goodness}}, {{faithfulness}},","synonyms":{"kindness":["gentleness"]}},"kjv":{"text":"But the fruit of the Spirit is love, joy, peace, longsuffering, {{gentleness}}, {{goodness}}, {{faith}},","synonyms":{"gentleness":["kindness"],"faith":["faithfulness"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"Psalm 119:105","hint":"A well-known psalm verse comparing God's word to a source of guidance for each step.","funFact":"An ancient Near Eastern oil lamp was a small clay dish that only illuminated about one step ahead, indicating step-by-step guidance rather than a searchlight showing the entire journey.","translations":{"modern":{"text":"Your word is a {{lamp}} to my feet and a {{light}} to my path.","easyIndex":1,"synonyms":{"light":["guide"]}},"kjv":{"text":"Thy word is a {{lamp}} unto my feet, and a {{light}} unto my path.","easyIndex":1,"synonyms":{"light":["guide"]}}}}$j$::jsonb),
('quote',null,$j${"reference":"Ephesians 2:8","hint":"Paul's summary of salvation as an unearned gift, not a human achievement.","funFact":"The very next verse, Ephesians 2:9, adds 'not by works, so that no one can boast' — reinforcing that salvation is not earned through effort.","translations":{"modern":{"text":"For by {{grace}} you have been saved through {{faith}}. And this is not your own doing; it is the {{gift}} of God.","easyIndex":1},"kjv":{"text":"For by {{grace}} are ye saved through {{faith}}; and that not of yourselves: it is the {{gift}} of God:","easyIndex":1}}}$j$::jsonb),
('quote',null,$j${"reference":"Hebrews 11:1","hint":"The Bible's own definition of faith, opening a chapter often called the 'faith hall of fame.'","funFact":"This verse opens a chapter that goes on to list Old Testament figures — including Abel, Noah, Abraham, and Moses — commended for their faith.","translations":{"modern":{"text":"Now faith is the {{assurance}} of things hoped for, the {{conviction}} of things not seen."},"kjv":{"text":"Now faith is the {{substance}} of things hoped for, the {{evidence}} of things not seen."}}}$j$::jsonb),
('quote',null,$j${"reference":"Psalm 46:1","hint":"A psalm of confidence often associated with Martin Luther's hymn 'A Mighty Fortress Is Our God.'","funFact":"This psalm is traditionally linked to the phrase 'be still, and know that I am God,' found later in the same chapter, in verse 10.","translations":{"modern":{"text":"God is our {{refuge}} and {{strength}}, a very present help in trouble."},"kjv":{"text":"God is our {{refuge}} and {{strength}}, a very present help in trouble."}}}$j$::jsonb),
('quote',null,$j${"reference":"Deuteronomy 31:6","hint":"Moses' charge to Israel before his death, echoing words later given to Joshua.","funFact":"This same charge — 'be strong and courageous' — is repeated to Joshua three times in the following chapter as he takes over leadership.","translations":{"modern":{"text":"Be {{strong}} and {{courageous}}. Do not fear or be in dread of them, for it is the Lord your God who goes with you. He will not leave you or {{forsake}} you."},"kjv":{"text":"Be {{strong}} and of a good {{courage}}, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor {{forsake}} thee."}}}$j$::jsonb),
('quote',null,$j${"reference":"Romans 10:9","hint":"Paul's concise statement of the heart-and-mouth confession at the center of salvation.","funFact":"This verse is often paired with Romans 10:13, 'everyone who calls on the name of the Lord will be saved,' as a classic 'Romans Road' salvation passage.","translations":{"modern":{"text":"if you {{confess}} with your mouth that Jesus is Lord and {{believe}} in your heart that God raised him from the dead, you will be {{saved}}."},"kjv":{"text":"That if thou shalt {{confess}} with thy mouth the Lord Jesus, and shalt {{believe}} in thine heart that God hath raised him from the dead, thou shalt be {{saved}}."}}}$j$::jsonb)
) as v(game, difficulty, payload)
where not exists (select 1 from public.game_questions where game = 'quote');
